SELECT COUNT(*) AS staging_relationships
FROM genre_staging;

SELECT *
FROM genre_staging
LIMIT 30;

SELECT DISTINCT
    s.genre_name
FROM genre_staging s
LEFT JOIN genres g
    ON s.genre_name = g.genre_name
WHERE g.genre_id IS NULL;

SELECT DISTINCT
    s.platform
FROM genre_staging s
LEFT JOIN platforms p
    ON s.platform = p.platform_name
WHERE p.platform_id IS NULL;

SELECT
    s.platform,
    s.title,
    COUNT(t.title_id) AS matching_titles
FROM genre_staging s

LEFT JOIN platforms p
    ON s.platform = p.platform_name

LEFT JOIN titles t
    ON t.platform_id = p.platform_id
    AND t.title = s.title

GROUP BY
    s.platform,
    s.title

HAVING COUNT(t.title_id) = 0

LIMIT 30;

-- Check for Duplicate Title Matches
SELECT
    p.platform_name,
    t.title,
    COUNT(*) AS duplicate_count

FROM titles t

JOIN platforms p
    ON t.platform_id = p.platform_id

GROUP BY
    p.platform_name,
    t.title

HAVING COUNT(*) > 1

ORDER BY duplicate_count DESC;

